    <style>
        .label { display:block; margin-bottom:.375rem; font-size:.75rem; font-weight:600; text-transform:uppercase; letter-spacing:.04em; color:#3f484c; }
        .field { width:100%; border-radius:.5rem; border-color:#e2e8f0; }
    </style>
    <script>
        document.querySelectorAll('input[type="radio"][data-patient]').forEach(input => input.addEventListener('change', () => {
            const target = input.form.id === 'consultation-form' ? 'consultation-patient-id' : 'analysis-patient-id';
            document.getElementById(target).value = input.dataset.patient;
            if (input.form.id === 'consultation-form') {
                window.location.href = `{{ route('doctor.consultations') }}?patient=${encodeURIComponent(input.dataset.patient)}`;
            }
        }));

        const prescriptionModal = document.getElementById('prescription-modal');
        const prescriptionLines = document.getElementById('prescription-lines');
        document.querySelector('[data-open-clinical]')?.addEventListener('click', () => {
            document.getElementById('clinical-form-panel')?.classList.remove('hidden');
            document.getElementById('clinical-form-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
        document.querySelectorAll('[data-open-prescription]').forEach(button => button.addEventListener('click', () => {
            const patientId = document.getElementById('consultation-patient-id')?.value;
            if (!patientId) return;
            document.getElementById('prescription-patient-id').value = patientId;
            prescriptionModal.classList.remove('hidden');
            prescriptionModal.classList.add('flex');
        }));
        document.querySelectorAll('[data-close-prescription]').forEach(button => button.addEventListener('click', () => {
            prescriptionModal.classList.add('hidden');
            prescriptionModal.classList.remove('flex');
        }));
        document.getElementById('add-prescription-line')?.addEventListener('click', () => {
            const line = prescriptionLines.firstElementChild.cloneNode(true);
            const index = prescriptionLines.children.length;
            line.querySelectorAll('input').forEach(input => {
                input.value = input.type === 'number' ? (input.name?.includes('duree_jours') ? '7' : '14') : '';
                if (input.name) input.name = input.name.replace(/\[\d+\]/, `[${index}]`);
            });
            line.querySelectorAll('.frequency').forEach(button => button.classList.remove('bg-primary', 'text-white'));
            prescriptionLines.appendChild(line);
        });
        prescriptionLines?.addEventListener('click', event => {
            const remove = event.target.closest('[data-remove-line]');
            if (remove && prescriptionLines.children.length > 1) remove.closest('.prescription-line').remove();
            const frequency = event.target.closest('.frequency');
            if (frequency) {
                frequency.parentElement.querySelectorAll('.frequency').forEach(button => button.classList.remove('bg-primary', 'text-white'));
                frequency.classList.add('bg-primary', 'text-white');
                frequency.parentElement.querySelector('input[type="hidden"]').value = frequency.dataset.frequency;
            }
        });
    </script>
